package org.joda.time.format;

import java.io.*;
import java.io.IOException;
import java.io.Writer;
import java.math.*;
import java.util.*;
import java.util.Locale;
import org.joda.time.Chronology;
import org.joda.time.DateTime;
import org.joda.time.DateTimeFieldType;
import org.joda.time.DateTimeUtils;
import org.joda.time.DateTimeZone;
import org.joda.time.DateTimeZoneMidday;
import org.joda.time.LocalDate;
import org.joda.time.LocalDateTime;
import org.joda.time.LocalTime;
import org.joda.time.MutableDateTime;
import org.joda.time.ReadWritableInstant;
import org.joda.time.ReadableInstant;
import org.joda.time.ReadablePartial;
import org.joda.time.format.DateTimeFormat;
import org.joda.time.format.DateTimeFormatter;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.mockito.Mockito;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.mockito.Mockito.*;

public class DateTimeFormatter_parseInto_TriageGen2Test {

    private DateTimeFormatter formatter;
    private ReadWritableInstant instant;

    @Before
    public void setUp() {
        // Using a standard formatter to avoid complex manual mocking of the internal parser logic
        formatter = DateTimeFormat.forPattern("yyyy-MM-dd").parseAs(DateTimeFormatter.class);
        instant = new MutableDateTime(LocalDateTime.now());
    }

    /**
     * Mock implementation of ReadWritableInstant to allow control over millis and chronology
     */
    private static class MutableInstant extends MutableDateTime {
        public MutableInstant(LocalDateTime dt) {
            super(dt);
        }
    }

    @Test(expected = IllegalArgumentException.class)
    public void testParseInto_NullInstant_ThrowsException() {
        formatter.parseInto(null, "2023-01-01", 0);
    }

    @Test
    public void testParseInto_StandardDate_ReturnsNewPosition() {
        String text = "2023-01-01";
        int position = 0;

        // Expected result: 2023-01-01 is 10 chars long
        int newPos = formatter.parseInto(instant, text, position);

        assertEquals(10, newPos);
        assertEquals(2023, instant.getYear());
        assertEquals(1, instant.getMonthOfYear());
        assertEquals(1, instant.getDayOfMonth());
    }

    @Test
    public void testParseInto_WithOffsetParsed_UpdatesZone() {
        // Pattern that includes offset
        DateTimeFormatter offsetFormatter = DateTimeFormat.forPattern("yyyy-MM-dd HH:mm Z")
                .withOffsetParsed()
                .parseAs(DateTimeFormatter.class);

        String text = "2023-01-01 12:00 +05:00";
        ReadWritableInstant mutableInstant = new MutableInstant(LocalDateTime.parse("2023-01-01T12:00:00"));

        int newPos = offsetFormatter.parseInto(mutableInstant, text, 0);

        assertEquals(20, newPos);
        // Verify offset was applied (checking zone via offset)
        assertEquals(5 * 3600, mutableInstant.getChronology().getZone().getOffset(mutableInstant.getMillis()));
    }

    @Test
    public void testParseInto_WithSpecificZone_OverridesZone() {
        // Formatter with a forced zone
        DateTimeZone targetZone = DateTimeZone.forID("America/New_York");
        DateTimeFormatter zoneFormatter = DateTimeFormat.forPattern("yyyy-MM-dd")
                .withZone(targetZone)
                .parseAs(DateTimeFormatter.class);

        String text = "2023-01-01";
        ReadWritableInstant mutableInstant = new MutableInstant(LocalDateTime.now());

        zoneFormatter.parseInto(mutableInstant, text, 0);

        assertEquals(targetZone, mutableInstant.getChronology().getZone());
    }

    @Test
    public void testParseInto_WithBucketZone_UpdatesChronology() {
        // Pattern that parses a zone from the string without 'withOffsetParsed' being explicitly set for the offset integer, 
        // but bucket might still provide a zone.
        DateTimeFormatter zoneFormatter = DateTimeFormat.forPattern("yyyy-MM-dd Z")
                .parseAs(DateTimeFormatter.class);

        String text = "2023-01-01 +02:00";
        ReadWritableInstant mutableInstant = new MutableInstant(LocalDateTime.now());

        zoneFormatter.parseInto(mutableInstant, text, 0);

        // The zone should be updated to +02:00
        assertEquals(7200, mutableInstant.getChronology().getZone().getOffset(mutableInstant.getMillis()));
    }

    @Test
    public void testParseInto_PartialMatch_ReturnsPosition() {
        // Testing behavior when text is longer than pattern
        DateTimeFormatter shortFormatter = DateTimeFormat.forPattern("yyyy")
                .parseAs(DateTimeFormatter.class);

        String text = "2023-05-05";
        int newPos = shortFormatter.parseInto(instant, text, 0);

        assertEquals(4, newPos);
        assertEquals(2023, instant.getYear());
    }

    /**
     * Helper class to satisfy the interface requirements in the test environment
     */
    private static class MockReadWritableInstant implements ReadWritableInstant {
        private long millis;
        private Chronology chronology = DateTimeZone.UTC.getChronology();

        @Override
        public long getMillis() { return millis; }
        @Override
        public void setMillis(long instantMillis) { this.millis = instantMillis; }
        @Override
        public Chronology getChronology() { return chronology; }
        @Override
        public void setChronology(Chronology chronology) { this.chronology = chronology; }
        @Override
        public DateTimeZone getZone() { return chronology.getZone(); }
        @Override
        public void setZone(DateTimeZone zone) { /* Not directly supported by standard Chronology without wrap */ }
    }
}
